 fun backendError(code:String,language:Language):String = text(when(code) {
    "AUTH" -> "backendAuthError"
    "INSUFFICIENT_INFORMATION","INPUT_LIMIT" -> "backendInputError"
    "OPENAI_AUTH","OPENAI_PERMISSION" -> "providerAuthError"
    "OPENAI_CREDIT" -> "providerCreditError"
    "TEST_BUDGET_LIMIT" -> "budgetError"
    "TEST_BUDGET_STATE" -> "budgetStateError"
    "DIRECT_CONFIGURATION" -> "directConfigError"
    "OPENAI_MODEL" -> "providerModelError"
    "BUSY","OPENAI_RATE_LIMIT" -> "backendBusyError"
    "OPENAI_NETWORK","BACKEND_UNAVAILABLE" -> "backendConnectionError"
    else -> "providerResponseError"
 },language)
 fun text(key:String,language:Language):String = (if(BuildConfig.DIRECT_OPENAI) personalStrings[key] else null)?.getOrNull(language.uiIndex) ?: strings[key]?.getOrNull(language.uiIndex) ?: key
}
